    "description": "Вы получаете себе в услужение фамильяра, духа, который принимает форму выбранного вами животного: летучей мыши, кота, краба, лягушки (жабы), ястреба, ящерицы, совы, осьминога, ядовитоый змени, рыбы, крысы, ворона, ласки, паука или морского конька. Он появляется в незанятом месте в пределах дальности заклинания. Параметры фамильяра зависят от выбранной формы, однако он принадлежит к божественным существам, феям или демонам (на ваш выбор). Ваш фамильяр действует независимо от вас, однако он всегда слушается ваших приказов. В бою он действует отдельно и требует отдельного броска инициативы. Фамильяр не может атаковать, но может совершать другие действия как обычно. Когда фамильяр находится в пределах 100 футов от вас, вы можете общаться с ним телепатически. Кроме того, в качестве действия вы можете видеть глазам фамильяра и слышать его ушами до начала вашего следующего хода, получая все особые чувства, которыми обладает фамильяр. В течение этого времени вы слепы и глухи по отношению к вашему собственному окружению. В качестве действия вы можете временно отозвать вашего фамильяра. Он исчезает в подпространстве где ожидает, пока вы его призовете. Вы также можете отпустить его навсегда. Пока фамильяр отозван, вы можете в качестве действия призвать его в любом незанятом месте в пределах 30 футов от вас. Вы не можете иметь более одного фамильяра за раз. Если вы произносите это заклинание, когда уже имеете одного фамильяра, вы можете придать ему новую форму. Выберите одну из вышеперечисленных и ваш фамильяр превратится в новое существо. Наконец, вы можете произнести касательное заклинание и ваш фамильяр доставит его цели, словно он сам произнес его. Ваш фамильяр должен быть в пределах 100 футов от вас и должен совершить реакцию, чтобы доставить заклинание, когда вы произносите его. Если заклинание требует броска атаки, вы используете ваш модификатор для броска.",
