    "description": "Вы призываете духа, который принимает форму невероятно умного, сильного и преданного скакуна, и создаете с ним связь. Скакун появляется в незанятом месте в пределах дальности заклинания и принимает выбранную вами форму. Это может быть боевой конь, пони, верблюд, лось или мастифф. (МП может позволить вам призывать и других животных.) Скакун имеет параметры свойственные этой форме, но принадлежит к божественным существам, феям или демонам (на ваш выбор) вместо своего нормального типа. Кроме того, если форма вашего скакуна имеет 5 или меньше Интеллекта, то он становится равным 6, а скакун получает способность понимать один язык на ваш выбор из тех, на которых вы умеете говорить. Ваш скакун служит вам средством передвижения как в бою, так и вне его, а ваша связь позволяет вам сражаться как единое целое. Когда вы верхом, любое ваше заклинание, которое применяется на вас, также воздействует на скакуна. Если ОЗ скакуна падают до 0, он исчезает, не оставляя за собой физической формы. Вы также можете отозвать его в любой момент в качестве действия, заставив его исчезнуть. В любом случае, повторное использование этого заклинания снова призывает его, восстанавливая его ОЗ до максимума. Пока ваш скакун находится в пределах 1 мили от вас, вы можете общаться с ним телепатически. Вы не можете иметь больше одного скакуна, связанного с вами этим заклинанием. В качестве действия, вы можете в любой момент освободить скакуна от связи, в результате чего он исчезнет.",
