    "description": "В указанном вами месте в пределах дальности заклинания появляется сфера радиусом 20 футов, заполненная ядовитым зеленовато-желтым туманом. Туман огибает углы. Он продолжается до тех пор, пока действует заклинание, или пока сильный ветер не развеет туман. Область действия считается сильно затемненной. Когда существо впервые за ход входит в область действия или начинает свой ход в ней, оно должно сделать спасбросок по Телосложению. В случае провала оно получает 5d8 урона ядом, а в случае успеха - половину этого урона. Существа подвергаются воздействию заклинания, даже если они задерживают дыхание или вовсе не нуждаются в дыхании. В начале каждого вашего хода туман сдвигается на 10 футов в противоположную от вас сторону. Поскольку пары тяжелее воздуха, они стелятся по земле, заполняя любые впадины. На более высоких кругах. Если вы произносите заклинание, используя ячейку 6 круга или выше, то урон увеличивается на 1d8 за каждый круг выше пятого.",
