    "description": "Выберите до десяти немагических. Средние цели считаются за два предмета, Большие - за четыре, Огромные - за восемь. Каждый предмет оживает и становится существом, которое вы контролируете. В качестве дополнительного действия, вы можете отдавать телепатические приказы любому существу, если оно находится в пределах 500 футов от вас. Вы выбираете, какое действие совершит существо и куда оно пойдет в свой следующий ход. Получив приказ, существо продолжает ему следовать, пока не выполнит поручение. Оживленный предмет считается големом, чьи КБ, ОЗ, атаки, Сила и Ловкость зависят от его размера. Скорость равна 30 футам. Предмет имеет слеповидение в радиусе 30 футов и не видит ничего за пределами этого радиуса. Когда ОЗ предмета падают до 0, он возвращается в нормальную форму, сохраняя все полученные повреждения. На более высоких кругах. Если вы произносите заклинание, используя ячейку 6 круга или выше,вы можете оживить два дополнительных предмета за каждый круг выше пятого.",
