    "description": "Вы обращаетесь за помощью к потусторонней сущности. Это может быть бог, изначальная сила, принц демонов или другое могущественная сущность, которую вы знаете. Эта сущность посылает лояльное ей божественное существо, элементаля или демона на помощь вам и оно появляется в любом незанятом месте в пределах дальности заклинания. Если вы знаете имя определенного существа, то можете попросить именно его, назвав его имя, когда произносите заклинание. Однако вы все равно можете получить другое существо (на усмотрение МП). Когда существо появляется, оно не обязано вести себя каким-либо образом. Вы можете попросить его об услуге в обмен на плату, но существо не обязано соглашаться. Услуги могут варьироваться от простых (перелететь через пропасть или помочь в бою) до сложных (шпионить за врагом или защищать группу во время исследования подземелья). Вы должны быть способны общаться с этим существом, чтобы попросить его об услуге. Плата также может быть разной. Божественное существо может попросить немалых пожертвований золота или магических предметов союзному храму, а демон может потребовать жертвоприношение или сокровище. Другие существа могут попросить сделать ответную услугу. Приблизительно, задача, которая требует несколько минут, стоит 100 зм за минуту. Задача, на которую уйдет несколько часов, стоит 1000 зм за час. А задача, которая займет несколько дней (до 10 дней), стоит 10000 зм за день. МП может изменять эти приблизительные расценки, в зависимости от условий, в которых вы произнесли это заклинание. Если услуга, о которой вы просите отвечает принципам и идеям существа, то оно может снизить плату вдвое или вовсе отказаться от нее. Неопасные задания как правило обходятся лишь в половину стоимости, тогда как особо опасные могут быть дороже. Существа редко берутся за задачи, которые кажутся самоубийственными. Когда существо выполнит задачу, или срок соглашения истечет, существо возвращается на свой родной план, предварительно отчитавшись перед вами, если это уместно и возможно. Если вы не смогли договориться с ним об оплате, то существо немедленно возвращается на свой родной план. Существо, которое присоединилось к группе, считается ее членом и получает свою долю очков опыта.",
