    "description": "Вы пытаетесь превратить одно существо, которое видите в пределах дальности заклинания, в камень. Если тело цели состоит из плоти, то оно должно сделать спасбросок по Телосложению. В случае провала оно обездвижено, а его плоть начинает твердеть. В случае успеха, заклинание не действует. Находясь под воздействием этого заклинания, существо должно делать спасбросок по Телосложению в конце каждого своего хода. Сделав три успешных спасброска, оно освобождается от заклинания. Сделав три неудачных - оно превращается в камень и считается окаменевшим до тех пор, пока действует заклинание. Успехи и провалы не должны быть последовательными. Если существо получает физические повреждения, будучи окаменевшим, то сохраняет эти повреждения, возвращаясь в нормальное состояние. Если вы поддерживаете концентрацию на этом заклинании до самого конца, то существо превращается в камень до тех пор, пока заклинание не будет развеяно.",
